import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CisoyQNf.js";var i=JSON.parse(`{"title":"Android Binder 同步调用的优先级继承机制","description":"解析 Android Binder 同步事务中的线程优先级继承、调度策略和内核恢复流程。","frontmatter":{"title":"Android Binder 同步调用的优先级继承机制","description":"解析 Android Binder 同步事务中的线程优先级继承、调度策略和内核恢复流程。","date":"2026-08-30T00:00:00.000Z","outline":"deep"},"headers":[],"relativePath":"blog/binder-priority-inheritance.md","filePath":"blog/binder-priority-inheritance.md","lastUpdated":1788105607000}`),a={name:`blog/binder-priority-inheritance.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="android-binder-同步调用的优先级继承机制" tabindex="-1">Android Binder 同步调用的优先级继承机制 <a class="header-anchor" href="#android-binder-同步调用的优先级继承机制" aria-label="Permalink to “Android Binder 同步调用的优先级继承机制”">​</a></h1><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to “摘要”">​</a></h2><p>Android Binder 支持在同步事务中把调用线程的调度策略和优先级带到被调用进程的 Binder 线程上，以缓解优先级反转问题。例如，应用 A 的前台线程调用服务 B 时，即使 B 的 Binder 线程原本处于较低优先级，B 也可以暂时使用 A 的优先级处理这次请求。</p><p>这套机制由用户态 libbinder 和内核 Binder 驱动共同完成。它不是简单地把“proxy 的优先级”复制给“stub”：proxy/stub 是 Binder 对象，真正参与调度的是 A 和 B 的线程。内核从发起事务的 <code>current</code> 线程读取优先级，在事务送达 B 的 Binder 线程时临时调整该线程，事务结束后恢复原值。</p><p>本文以 AOSP Android 16 为例，源码基线为 <code>android-16.0.0_r4</code>；内核侧参考 <code>kernel/common</code> 的 <code>android16-6.12</code> 分支。</p><h2 id="一、几个基本概念" tabindex="-1">一、几个基本概念 <a class="header-anchor" href="#一、几个基本概念" aria-label="Permalink to “一、几个基本概念”">​</a></h2><h3 id="_1-优先级属于线程" tabindex="-1">1. 优先级属于线程 <a class="header-anchor" href="#_1-优先级属于线程" aria-label="Permalink to “1. 优先级属于线程”">​</a></h3><p>Binder proxy 和 stub 本身不执行代码，也没有独立的调度实体。执行过程是：</p><ul><li>A 的某个线程调用 B 的 proxy；</li><li>内核将事务投递给 B 进程中的某个 Binder 线程；</li><li>该 Binder 线程执行 B 的 stub/onTransact。</li></ul><p>因此，本文中的“A 的高优先级”指发起 Binder 调用的 A 线程，“B 的低优先级”指实际处理事务的 B Binder 线程。</p><h3 id="_2-linux-调度策略和优先级" tabindex="-1">2. Linux 调度策略和优先级 <a class="header-anchor" href="#_2-linux-调度策略和优先级" aria-label="Permalink to “2. Linux 调度策略和优先级”">​</a></h3><p>Binder 驱动支持以下策略：</p><ul><li><code>SCHED_NORMAL</code></li><li><code>SCHED_BATCH</code></li><li><code>SCHED_FIFO</code></li><li><code>SCHED_RR</code></li></ul><p>普通调度策略使用 nice 值（用户态范围通常为 <code>-20..19</code>），实时策略使用 RT priority（通常为 <code>1..99</code>）。内核 <code>task_struct::prio</code> 使用另一套数值表示：数值越小，调度优先级越高。</p><h2 id="二、同步-binder-调用的完整流程" tabindex="-1">二、同步 Binder 调用的完整流程 <a class="header-anchor" href="#二、同步-binder-调用的完整流程" aria-label="Permalink to “二、同步 Binder 调用的完整流程”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>A 高优先级线程</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>    | BpBinder::transact()</span></span>
<span class="line"><span>    v</span></span>
<span class="line"><span>libbinder: IPCThreadState::transact()</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>    | BC_TRANSACTION，TF_ONE_WAY 未设置</span></span>
<span class="line"><span>    v</span></span>
<span class="line"><span>内核 binder_transaction()</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>    | 保存 A 当前线程的 sched_policy/prio</span></span>
<span class="line"><span>    v</span></span>
<span class="line"><span>内核 binder_proc_transaction()</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>    | 选择或唤醒 B 的 Binder 线程</span></span>
<span class="line"><span>    v</span></span>
<span class="line"><span>binder_transaction_priority()</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>    | 计算实际目标优先级并临时设置 B 线程</span></span>
<span class="line"><span>    v</span></span>
<span class="line"><span>B Binder 线程执行 Stub/onTransact()</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>    | 返回同步 reply</span></span>
<span class="line"><span>    v</span></span>
<span class="line"><span>Binder 驱动恢复 B 线程原来的优先级</span></span></code></pre></div><h3 id="_1-用户态发起同步事务" tabindex="-1">1. 用户态发起同步事务 <a class="header-anchor" href="#_1-用户态发起同步事务" aria-label="Permalink to “1. 用户态发起同步事务”">​</a></h3><p><code>BpBinder::transact()</code> 最终调用 <code>IPCThreadState::transact()</code>：<a href="https://android.googlesource.com/platform/frameworks/native/+/refs/tags/android-16.0.0_r4/libs/binder/BpBinder.cpp#L394" target="_blank" rel="noreferrer">BpBinder.cpp:394</a>、<a href="https://android.googlesource.com/platform/frameworks/native/+/refs/tags/android-16.0.0_r4/libs/binder/IPCThreadState.cpp#L919" target="_blank" rel="noreferrer">IPCThreadState.cpp:919</a>。</p><p><code>TF_ONE_WAY</code> 未设置时，libbinder 会等待 <code>BR_REPLY</code>，因此这是同步调用：<a href="https://android.googlesource.com/platform/frameworks/native/+/refs/tags/android-16.0.0_r4/libs/binder/IPCThreadState.cpp#L946" target="_blank" rel="noreferrer">IPCThreadState.cpp:946</a>。</p><h3 id="_2-内核保存调用线程优先级" tabindex="-1">2. 内核保存调用线程优先级 <a class="header-anchor" href="#_2-内核保存调用线程优先级" aria-label="Permalink to “2. 内核保存调用线程优先级”">​</a></h3><p>在创建事务时，驱动检查当前事务是否为同步事务，并读取发起线程的 <code>current-&gt;policy</code> 和 <code>current-&gt;prio</code>：<a href="https://android.googlesource.com/kernel/common/+/refs/heads/android16-6.12/drivers/android/binder.c#L3575" target="_blank" rel="noreferrer">binder.c:3575</a>。</p><div class="language-c"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(t</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flags </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TF_ONE_WAY) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&amp;&amp;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    binder_supported_policy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(current</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">policy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    t-&gt;priority.sched_policy </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> current-&gt;policy;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    t-&gt;priority.prio </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> current-&gt;prio;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>如果发起线程使用 Binder 不支持的调度策略，则事务使用目标进程的默认优先级。异步事务也使用目标进程默认优先级，而不是调用者优先级。</p><h3 id="_3-选择目标线程并更新优先级" tabindex="-1">3. 选择目标线程并更新优先级 <a class="header-anchor" href="#_3-选择目标线程并更新优先级" aria-label="Permalink to “3. 选择目标线程并更新优先级”">​</a></h3><p>驱动选择 B 进程中可用的 Binder 线程；有明确目标线程时，事务进入该线程的 todo 队列，并调用 <code>binder_transaction_priority()</code>：<a href="https://android.googlesource.com/kernel/common/+/refs/heads/android16-6.12/drivers/android/binder.c#L3078" target="_blank" rel="noreferrer">binder.c:3078</a>。</p><p>如果事务暂时只能放入进程队列，则在 B 线程从队列取出事务时再次执行相同的优先级处理：<a href="https://android.googlesource.com/kernel/common/+/refs/heads/android16-6.12/drivers/android/binder.c#L5302" target="_blank" rel="noreferrer">binder.c:5302</a>。事务对象中的 <code>set_priority_called</code> 保证一次事务不会重复设置。</p><h2 id="三、实际优先级如何计算" tabindex="-1">三、实际优先级如何计算 <a class="header-anchor" href="#三、实际优先级如何计算" aria-label="Permalink to “三、实际优先级如何计算”">​</a></h2><p>可以把内核逻辑概括为：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>desired = 同步调用者的优先级</span></span>
<span class="line"><span>          或目标进程默认优先级</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果 desired 是 RT 策略且 Binder node 未允许 RT 继承：</span></span>
<span class="line"><span>    desired = SCHED_NORMAL/nice 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果 node 配置的最低优先级高于 desired：</span></span>
<span class="line"><span>    desired = node 的最低优先级</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最后根据 B 线程的 CAP_SYS_NICE、RLIMIT_RTPRIO、RLIMIT_NICE 做权限和范围限制</span></span></code></pre></div><p>核心实现位于 <a href="https://android.googlesource.com/kernel/common/+/refs/heads/android16-6.12/drivers/android/binder.c#L812" target="_blank" rel="noreferrer">binder.c:812</a>。node 的最低优先级更高时会覆盖调用者优先级；如果优先级相同，<code>SCHED_FIFO</code> 优先于 <code>SCHED_RR</code>，因为 FIFO 没有 RR 的时间片限制：<a href="https://android.googlesource.com/kernel/common/+/refs/heads/android16-6.12/drivers/android/binder.c#L835" target="_blank" rel="noreferrer">binder.c:835</a>。</p><p>因此，这不是无条件的“完全复制”：</p><ul><li>B 可以通过 node 配置要求一个最低优先级；</li><li>B 没有足够的调度权限时，RT/nice 请求可能被限制；</li><li>RT 策略默认不会跨进程继承，必须显式打开；</li><li>调用者使用不支持的调度策略时不会按调用者策略继承。</li></ul><h2 id="四、用户态配置" tabindex="-1">四、用户态配置 <a class="header-anchor" href="#四、用户态配置" aria-label="Permalink to “四、用户态配置”">​</a></h2><h3 id="_1-设置-binder-node-的最低调度策略" tabindex="-1">1. 设置 Binder node 的最低调度策略 <a class="header-anchor" href="#_1-设置-binder-node-的最低调度策略" aria-label="Permalink to “1. 设置 Binder node 的最低调度策略”">​</a></h3><p>Native libbinder 提供 <code>BBinder::setMinSchedulerPolicy()</code>：<a href="https://android.googlesource.com/platform/frameworks/native/+/refs/tags/android-16.0.0_r4/libs/binder/include/binder/Binder.h#L73" target="_blank" rel="noreferrer">Binder.h:73</a>。</p><div class="language-cpp"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">service-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setMinSchedulerPolicy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(SCHED_FIFO, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>该配置必须在 Binder 对象被发送到其他进程之前完成。对象被 parcel 后再修改会触发致命检查。NDK 平台接口对应 <code>AIBinder_setMinSchedulerPolicy()</code>。</p><h3 id="_2-允许-rt-优先级继承" tabindex="-1">2. 允许 RT 优先级继承 <a class="header-anchor" href="#_2-允许-rt-优先级继承" aria-label="Permalink to “2. 允许 RT 优先级继承”">​</a></h3><div class="language-cpp"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">service-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setInheritRt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p><code>setInheritRt(true)</code> 只控制 <code>SCHED_FIFO</code>/<code>SCHED_RR</code> 是否可以从同步调用者继承，不影响普通 <code>SCHED_NORMAL</code> 优先级的继承。它最终被编码为 <code>FLAT_BINDER_FLAG_INHERIT_RT</code>：<a href="https://android.googlesource.com/platform/frameworks/native/+/refs/tags/android-16.0.0_r4/libs/binder/Parcel.cpp#L321" target="_blank" rel="noreferrer">Parcel.cpp:321</a>、<a href="https://android.googlesource.com/kernel/common/+/refs/heads/android16-6.12/include/uapi/linux/android/binder.h#L85" target="_blank" rel="noreferrer">binder.h:85</a>。</p><p>Java 层提供了隐藏 API <code>Binder.setInheritRt()</code>：<a href="https://android.googlesource.com/platform/frameworks/base/+/refs/tags/android-16.0.0_r4/core/java/android/os/Binder.java#L1294" target="_blank" rel="noreferrer">Binder.java:1294</a>。</p><h3 id="_3-全局-rt-继承" tabindex="-1">3. 全局 RT 继承 <a class="header-anchor" href="#_3-全局-rt-继承" aria-label="Permalink to “3. 全局 RT 继承”">​</a></h3><p>libbinder 默认关闭全局 RT 继承，<code>BBinder::setGlobalInheritRt(true)</code> 可以设置进程级默认值。该默认值应尽早设置，因为 Binder 对象发送出去后，其 flags 已经固定。</p><p>Android 16 的 system_server 只有在 feature flag 和系统属性同时开启时才启用它：<a href="https://android.googlesource.com/platform/frameworks/base/+/refs/tags/android-16.0.0_r4/services/java/com/android/server/SystemServer.java#L1027" target="_blank" rel="noreferrer">SystemServer.java:1027</a>。</p><h3 id="_4-关闭默认后台调度" tabindex="-1">4. 关闭默认后台调度 <a class="header-anchor" href="#_4-关闭默认后台调度" aria-label="Permalink to “4. 关闭默认后台调度”">​</a></h3><p>当 Binder 对象被 flatten 时，如果没有调用 <code>disableBackgroundScheduling(true)</code>，libbinder 默认会给 node 编码 <code>SCHED_NORMAL/nice 19</code> 的调度配置：<a href="https://android.googlesource.com/platform/frameworks/native/+/refs/tags/android-16.0.0_r4/libs/binder/Parcel.cpp#L283" target="_blank" rel="noreferrer">Parcel.cpp:283</a>。这就是“Binder 线程默认较低优先级”的主要来源之一。</p><p>system_server 启动时显式关闭该默认行为，确保进入 system_server 的 Binder 调用使用前台优先级：<a href="https://android.googlesource.com/platform/frameworks/base/+/refs/tags/android-16.0.0_r4/services/java/com/android/server/SystemServer.java#L928" target="_blank" rel="noreferrer">SystemServer.java:928</a>。Native/NDK 对应 <code>IPCThreadState::disableBackgroundScheduling()</code> 和 <code>ABinderProcess_disableBackgroundScheduling()</code>。</p><h2 id="五、事务结束后的恢复" tabindex="-1">五、事务结束后的恢复 <a class="header-anchor" href="#五、事务结束后的恢复" aria-label="Permalink to “五、事务结束后的恢复”">​</a></h2><p>设置 B 线程优先级前，驱动会保存其原来的策略和优先级到事务对象：<a href="https://android.googlesource.com/kernel/common/+/refs/heads/android16-6.12/drivers/android/binder.c#L848" target="_blank" rel="noreferrer">binder.c:848</a>。</p><p>同步 reply 返回、事务失败或目标线程死亡时，驱动调用 <code>binder_restore_priority()</code> 恢复原值：<a href="https://android.googlesource.com/kernel/common/+/refs/heads/android16-6.12/drivers/android/binder.c#L4001" target="_blank" rel="noreferrer">binder.c:4001</a>。Binder 线程重新进入等待进程队列工作时，也会恢复到进程默认优先级：<a href="https://android.googlesource.com/kernel/common/+/refs/heads/android16-6.12/drivers/android/binder.c#L5024" target="_blank" rel="noreferrer">binder.c:5024</a>。</p><h3 id="嵌套同步调用" tabindex="-1">嵌套同步调用 <a class="header-anchor" href="#嵌套同步调用" aria-label="Permalink to “嵌套同步调用”">​</a></h3><p>如果 B 在处理 A 的请求期间，又同步调用 C，那么 B 当前 Binder 线程此时已经带有 A 的优先级。C 的事务会以 B 当前线程的优先级作为调用者优先级，因此优先级可以沿着同步调用链继续传递。</p><p>驱动通过 <code>prio_state</code>、<code>prio_next</code> 和事务的 <code>saved_priority</code> 处理嵌套调用，避免 C 返回时错误覆盖 B 仍在处理 A 请求所需的优先级。</p><h2 id="六、同步与异步事务的区别" tabindex="-1">六、同步与异步事务的区别 <a class="header-anchor" href="#六、同步与异步事务的区别" aria-label="Permalink to “六、同步与异步事务的区别”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>同步事务</th><th>异步事务（one-way）</th></tr></thead><tbody><tr><td>标志</td><td>未设置 <code>TF_ONE_WAY</code></td><td>设置 <code>TF_ONE_WAY</code></td></tr><tr><td>调用者等待 reply</td><td>是</td><td>否</td></tr><tr><td>是否继承调用线程优先级</td><td>是，前提是策略受支持</td><td>否</td></tr><tr><td>优先级来源</td><td>调用线程 + node 最低优先级</td><td>目标进程默认优先级 + node 配置</td></tr><tr><td>是否在结束后恢复</td><td>是</td><td>不发生调用者优先级捐赠</td></tr></tbody></table><h2 id="七、如何验证和调试" tabindex="-1">七、如何验证和调试 <a class="header-anchor" href="#七、如何验证和调试" aria-label="Permalink to “七、如何验证和调试”">​</a></h2><p>优先级调整是事务处理期间的短暂状态，事务结束后 <code>/proc</code> 中通常看不到变化。建议使用 Binder tracepoint：</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;echo 1 &gt; /sys/kernel/tracing/events/binder/binder_set_priority/enable&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;cat /sys/kernel/tracing/trace_pipe&#39;</span></span></code></pre></div><p><code>binder_set_priority</code> 事件会记录：</p><ul><li>Binder 进程和线程 ID；</li><li>调整前优先级 <code>old_prio</code>；</li><li>实际设置值 <code>new_prio</code>；</li><li>计算出的目标值 <code>desired_prio</code>。</li></ul><p>tracepoint 定义见 <a href="https://android.googlesource.com/kernel/common/+/refs/heads/android16-6.12/drivers/android/binder_trace.h#L79" target="_blank" rel="noreferrer">binder_trace.h:79</a>。测试时应同时记录事务是否为 <code>TF_ONE_WAY</code>、调用线程的调度策略、目标 Binder node 是否设置 <code>inherit_rt</code>，以及 B 线程的 <code>RLIMIT_RTPRIO/RLIMIT_NICE</code>。</p><h2 id="八、源码索引" tabindex="-1">八、源码索引 <a class="header-anchor" href="#八、源码索引" aria-label="Permalink to “八、源码索引”">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>关键位置</th><th>作用</th></tr></thead><tbody><tr><td>libbinder</td><td><a href="https://android.googlesource.com/platform/frameworks/native/+/refs/tags/android-16.0.0_r4/libs/binder/BpBinder.cpp#L394" target="_blank" rel="noreferrer">BpBinder.cpp:394</a></td><td>Proxy 发起事务</td></tr><tr><td>libbinder</td><td><a href="https://android.googlesource.com/platform/frameworks/native/+/refs/tags/android-16.0.0_r4/libs/binder/IPCThreadState.cpp#L919" target="_blank" rel="noreferrer">IPCThreadState.cpp:919</a></td><td>写入 <code>BC_TRANSACTION</code> 并等待同步 reply</td></tr><tr><td>libbinder</td><td><a href="https://android.googlesource.com/platform/frameworks/native/+/refs/tags/android-16.0.0_r4/libs/binder/Parcel.cpp#L283" target="_blank" rel="noreferrer">Parcel.cpp:283</a></td><td>编码 node 的调度配置</td></tr><tr><td>libbinder</td><td><a href="https://android.googlesource.com/platform/frameworks/native/+/refs/tags/android-16.0.0_r4/libs/binder/Binder.cpp#L605" target="_blank" rel="noreferrer">Binder.cpp:605</a></td><td>设置 node 最低调度策略</td></tr><tr><td>内核驱动</td><td><a href="https://android.googlesource.com/kernel/common/+/refs/heads/android16-6.12/drivers/android/binder.c#L3575" target="_blank" rel="noreferrer">binder.c:3575</a></td><td>保存同步调用者优先级</td></tr><tr><td>内核驱动</td><td><a href="https://android.googlesource.com/kernel/common/+/refs/heads/android16-6.12/drivers/android/binder.c#L812" target="_blank" rel="noreferrer">binder.c:812</a></td><td>计算并设置目标线程优先级</td></tr><tr><td>内核驱动</td><td><a href="https://android.googlesource.com/kernel/common/+/refs/heads/android16-6.12/drivers/android/binder.c#L4001" target="_blank" rel="noreferrer">binder.c:4001</a></td><td>reply 后恢复优先级</td></tr></tbody></table><p>Android 16 的 <code>kernel/common</code> 还包含一份可选的 Rust Binder 实现；其 <code>transaction.rs</code> 中的 <code>on_thread_selected()</code> 实现了同样的优先级决策：<a href="https://android.googlesource.com/kernel/common/+/refs/heads/android16-6.12/drivers/android/binder/transaction.rs#L582" target="_blank" rel="noreferrer">transaction.rs:582</a>。Kconfig 说明默认使用 C 实现，只有通过 <code>binder.impl=rust</code> 才选择 Rust 实现：<a href="https://android.googlesource.com/kernel/common/+/refs/heads/android16-6.12/drivers/android/binder/Kconfig#L4" target="_blank" rel="noreferrer">Kconfig:4</a>。</p><h2 id="九、结论" tabindex="-1">九、结论 <a class="header-anchor" href="#九、结论" aria-label="Permalink to “九、结论”">​</a></h2><p>Android Binder 的同步优先级机制可以概括为：</p><ol><li>内核从同步调用者线程读取调度策略和优先级；</li><li>事务送达目标 Binder 线程前，计算调用者优先级与 node 最低优先级的较高者；</li><li>RT 策略只有在目标 node 允许时才继承；</li><li>权限和 rlimit 会限制最终可设置的值；</li><li>reply 或错误返回后恢复目标线程原来的优先级；</li><li>嵌套同步调用可以沿调用链继续传递优先级。</li></ol><p>因此，用户看到的“高优先级 A 调用低优先级 B 时，B 临时变成高优先级”确实存在，但准确名称和语义是 Binder 的同步事务优先级继承/捐赠，而不是 proxy/stub 对象之间永久复制优先级。</p>`,68)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};